# Test pattern: cells shoot up-left if their diagonal neighbor is not blocked

output = [[4]*21 for _ in range(23)]

test_cells = [(15,11,5), (15,12,8), (16,11,9), (16,12,2), (17,10,9), (17,13,2)]
for r, c, v in test_cells:
    output[r][c] = v

print("Initial output grid:")
for row in output:
    print(" ".join(map(str, row)))

print("\nShooting analysis:")
shooting_cells = []
non_shooting = []

for r, c, v in test_cells:
    nr, nc = r-1, c-1
    # Check bounds
    if nr < 0 or nc < 0:
        shooting_cells.append((r,c,v))
        print(f"  {v} at ({r},{c}) - can't shoot (out of bounds)")
    else:
        val = output[nr][nc]
        block = val != 4  # non-bg blocks
        if not block:
            shooting_cells.append((r,c,v))
            print(f"  {v} at ({r},{c}) - up-left ({nr},{nc})={val}, NO BLOCK - shoots")
        else:
            non_shooting.append((r,c,v))
            print(f"  {v} at ({r},{c}) - up-left ({nr},{nc})={val}, BLOCKED")

print("\nDetermined: shooting cells = ", shooting_cells)
print("Determined: non-shooting = ", non_shooting)

# Now add the trails
trails = {}  # (r,c) -> value
for r, c, v in shooting_cells:
    # Trail goes up-left: (r-1,c-1), (r-2,c-2), ... until edge
    for k in range(1, 24):
        nr, nc = r-k, c-k
        if nr < 0 or nc < 0:
            break
        # Don't overwrite original cells
        if (nr, nc) != (r1, c1) for (r1,c1,_ ) in test_cells:
            raise NameError
        trails[(nr, nc)] = v

# Apply trails
for (r, c), v in trails.items():
    output[r][c] = v  # This will overwrite in wrong order!

# Better: collect then apply in correct order
final = [[4]*21 for _ in range(23)]
for r, c, v in test_cells:
    final[r][c] = v  # Keep originals
for (r, c), v in trails.items():
    if final[r][c] == 4:  # Only overwrite if hasn't been written
        final[r][c] = v

# Hmm, but this preserves order issue. Let me try last-writer-wins
final = [[4]*21 for _ in range(23)]
trails_ordered = []
for r, c, v in shooting_cells:
    for k in range(1, 24):
        nr, nc = r-k, c-k
        if nr < 0 or nc < 0:
            break
        if nr == 17 and nc == 13:
            continue  # Original 2
        if nr == 16 and nc == 12:
            continue  # Original 2
        if nr == 16 and nc == 11:
            continue  # Original 9
        if nr in (15, 17) and nc in (11, 12, 10, 13):
            continue  # More originals
        trails_ordered.append(((nr, nc), v, r, c, k))

for (tr, val), origvr, origcr, origk in [(item, item[2], item[3], item[4]) for item in trails_ordered]:
    pass

# Let me simplify
final = [[4]*21 for _ in range(23)]
for r, c, v in test_cells:
    final[r][c] = v

print("\nBefore trails:")
for row in final:
    print(" ".join(map(str, row)))

# Apply the trails to the output grid

